sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    try {
        // ── 1. RESOLVE CUSTOMER RECORD ──────────────────────────────────────
        var custGr = current;
        if (!custGr || !custGr.isValidRecord()) {
            template.print("<div style='font-family: Arial, sans-serif; color: #d9534f;'>Customer record unavailable (Preview mode)</div>");
            return;
        }

        // Scoped-safe HTML escape helper
        function esc(str) {
            if (str === null || str === undefined) return '';
            return (str + '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        // Basic customer fields
        var custName = custGr.getValue('customer_name') || 'Customer';
        var pan      = custGr.getValue('pan') || '—';
        var custCode = custGr.getValue('customer_code_sap') || '—';

        // Retrieve Link: Prioritize event.parm2 from eventQueue, fallback to record field
        var requestLink = (event && event.parm2) ? (event.parm2 + '').trim() : (custGr.getValue('request_link') || '');

        // Set Dynamic Email Subject Line
        email.setSubject('Action Required: Secure Data Upload Link for ' + custName);

        // ── 2. CALCULATE EXPIRY (3 DAYS VALIDITY) ───────────────────────────
        var expiryFormatted = '';
        try {
            var sentOn = custGr.getValue('link_sent_on');
            var gdt = sentOn ? new GlideDateTime(sentOn) : new GlideDateTime();
            gdt.addDaysLocalTime(3);

            var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            var day = ('0' + gdt.getDayOfMonthLocalTime()).slice(-2);
            var month = months[gdt.getMonthLocalTime() - 1] || 'Oct';
            var year = gdt.getYearLocalTime();

            var disp = gdt.getDisplayValue();
            var timePart = disp.indexOf(' ') > -1 ? disp.split(' ')[1] : '17:00:00';
            var timeParts = timePart.split(':');
            var hh = parseInt(timeParts[0], 10);
            var mm = timeParts[1] || '00';
            var ampm = hh >= 12 ? 'PM' : 'AM';
            hh = hh % 12;
            hh = hh ? hh : 12;
            var formattedHh = ('0' + hh).slice(-2);

            expiryFormatted = day + '-' + month + '-' + year + ', ' + formattedHh + ':' + mm + ' ' + ampm;
        } catch (eDate) {
            expiryFormatted = '3 days from issue date';
        }

        // ── 3. RESOLVE ASSIGNED TSH DETAILS ─────────────────────────────────
        var tshName = 'Territory Sales Head';
        var tshPhone = '';
        try {
            if (custGr.isValidField('tsh') && custGr.getValue('tsh')) {
                var tshGr = custGr.tsh.getRefRecord();
                if (tshGr && tshGr.isValidRecord()) {
                    if (tshGr.getTableName() === 'x_birl3_clm_tsh') {
                        var userGr = tshGr.name ? tshGr.name.getRefRecord() : null;
                        if (userGr && userGr.isValidRecord()) {
                            tshName = userGr.getValue('name') || tshName;
                            tshPhone = userGr.getValue('mobile_phone') || userGr.getValue('phone') || '';
                        } else {
                            tshName = tshGr.getDisplayValue('name') || tshName;
                            tshPhone = tshGr.getValue('phone') || tshGr.getValue('mobile') || '';
                        }
                    } else {
                        tshName = tshGr.getValue('name') || tshGr.getDisplayValue();
                        tshPhone = tshGr.getValue('mobile_phone') || tshGr.getValue('phone') || '';
                    }
                }
            }
        } catch (eTsh) {
            // Safe fallback
        }

        // ── 4. ASSEMBLE HTML BODY ───────────────────────────────────────────
        var h = '';

        // Salutation & Intro
        h += '<p style="margin: 0 0 16px 0; font-size: 15px; line-height: 1.5; color: #1a1a1a;">Dear <strong>' + esc(custName) + '</strong>,</p>';
        h += '<p style="margin: 0 0 16px 0; font-size: 14px; line-height: 1.6; color: #3a4451;">';
        h += 'Thank you for your continued association with <strong style="color: #1a1a1a;">UltraTech Cement</strong>.';
        h += '</p>';
        h += '<p style="margin: 0 0 22px 0; font-size: 14px; line-height: 1.6; color: #3a4451;">';
        h += 'To support your growing business requirements and facilitate the assessment of the appropriate credit limit, we request you to share your latest business and financial information through our secure digital platform.';
        h += '</p>';

        // Customer Details Card
        h += '<div style="margin-bottom: 24px; border: 1px solid #e0e6ed; border-radius: 6px; background-color: #fafbfc; overflow: hidden;">';
        h += '  <div style="padding: 10px 16px; background-color: #f1f3f7; border-bottom: 1px solid #dde3ea; font-size: 12px; font-weight: bold; text-transform: uppercase; letter-spacing: 0.8px; color: #1a1a1a;">';
        h += '    Customer Details';
        h += '  </div>';
        h += '  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="font-size: 13.5px; border-collapse: collapse;">';
        h += '    <tr>';
        h += '      <td width="36%" style="padding: 10px 16px; color: #5a6a7a; border-bottom: 1px solid #edf1f5;">PAN</td>';
        h += '      <td style="padding: 10px 16px; color: #1a1a1a; font-weight: 700; font-family: monospace; border-bottom: 1px solid #edf1f5;">' + esc(pan) + '</td>';
        h += '    </tr>';
        h += '    <tr>';
        h += '      <td style="padding: 10px 16px; color: #5a6a7a; border-bottom: 1px solid #edf1f5;">Customer Code</td>';
        h += '      <td style="padding: 10px 16px; color: #1a1a1a; font-weight: 700; border-bottom: 1px solid #edf1f5;">' + esc(custCode) + '</td>';
        h += '    </tr>';
        h += '    <tr>';
        h += '      <td style="padding: 10px 16px; color: #5a6a7a;">Link Valid Till</td>';
        h += '      <td style="padding: 10px 16px; color: #AF272F; font-weight: 700;">' + esc(expiryFormatted) + '</td>';
        h += '    </tr>';
        h += '  </table>';
        h += '</div>';

        // Call-to-Action Upload Button
        h += '<p style="margin: 0 0 14px 0; font-size: 14px; color: #3a4451;">Please upload the required documents using the secure link below:</p>';
        h += '<table role="presentation" border="0" cellspacing="0" cellpadding="0" style="margin-bottom: 24px;"><tbody><tr>';
        h += '  <td align="center" bgcolor="#E87722" style="border-radius: 6px;">';
        h += '    <a href="' + requestLink + '" target="_blank" rel="noopener" style="display: inline-block; padding: 13px 32px; font-family: \'Segoe UI\', Arial, sans-serif; font-size: 14px; font-weight: bold; color: #ffffff; text-decoration: none; border-radius: 6px; letter-spacing: 0.5px;">';
        h += '      Upload Data Here &rarr;';
        h += '    </a>';
        h += '  </td>';
        h += '</tr></tbody></table>';

        // Document Checklist Box
        h += '<div style="margin-bottom: 22px; padding: 16px 18px; border: 1px solid #e0e6ed; border-left: 4px solid #E87722; border-radius: 6px; background-color: #ffffff;">';
        h += '  <div style="font-size: 13px; font-weight: 700; color: #1a1a1a; margin-bottom: 8px;">';
        h += '    Please keep these ready if available <span style="font-size: 11px; font-weight: bold; color: #c0392b; background-color: #fdeeed; padding: 2px 6px; border-radius: 3px; margin-left: 4px;">PDF only</span>';
        h += '  </div>';
        h += '  <ul style="margin: 0; padding-left: 20px; font-size: 13px; color: #3a4451; line-height: 1.7;">';
        h += '    <li><strong>Income Tax Returns</strong> &ndash; last 3 years</li>';
        h += '    <li><strong>Profit &amp; Loss and Balance Sheet</strong> &ndash; last 3 years</li>';
        h += '    <li><strong>GST returns</strong> &ndash; last 1 year</li>';
        h += '  </ul>';
        h += '</div>';

        // Submission Notice
        h += '<p style="margin: 0 0 16px 0; font-size: 13.5px; line-height: 1.6; color: #5a6a7a;">';
        h += 'You will receive a one-time password (OTP) by email when you submit. The form can be submitted only once.';
        h += '</p>';

        // Contact TSH Info
        h += '<p style="margin: 0 0 20px 0; font-size: 13.5px; line-height: 1.6; color: #3a4451;">';
        h += 'If you <strong>Need help</strong>, you may please contact <strong style="color: #1a1a1a;">' + esc(tshName) + '</strong>, Territory Sales Head' + (tshPhone ? (', <strong>' + esc(tshPhone) + '</strong>') : '') + '.';
        h += '</p>';

        // Fallback Link Box
        if (requestLink) {
            h += '<div style="margin-bottom: 22px; padding: 12px 14px; background-color: #f4f5f7; border: 1px dashed #cdd4dc; border-radius: 6px; font-size: 12px; color: #5a6a7a;">';
            h += '  <div style="margin-bottom: 4px; font-weight: bold; color: #3a4451;">Having trouble with the button? Copy and paste this link:</div>';
            h += '  <a href="' + requestLink + '" target="_blank" style="color: #AF272F; word-break: break-all; text-decoration: underline;">' + requestLink + '</a>';
            h += '</div>';
        }

        // Closing
        h += '<p style="margin: 0 0 6px 0; font-size: 13.5px; line-height: 1.6; color: #3a4451;">';
        h += 'Your timely submission will help us complete the assessment efficiently and continue supporting your business needs.';
        h += '</p>';
        h += '<p style="margin: 0; font-size: 13.5px; line-height: 1.6; color: #3a4451;">Thank you for your cooperation.</p>';

        // Render into the template
        template.print(h);

    } catch (err) {
        gs.error('[clm.trade_doc_submission.details] Exception: ' + err.message);
        template.print('<div style="color:red; font-size:12px; padding:10px;">Error rendering email details: ' + esc(err.message) + '</div>');
    }
})(current, template, email, email_action, event);
